{
  "units": [
    {
      "quote_ref": "F000:F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section heading and title for 29 CFR 1910.38, designating emergency action plans without establishing substantive operational requirements."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An employer must have an emergency action plan whenever an OSHA standard in 29 CFR part 1910 requires one, and the requirements of 29 CFR 1910.38 apply to each such emergency action plan."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An emergency action plan must be in writing, kept in the workplace, and available to employees for review, subject to the oral communication exception for employers with 10 or fewer employees."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "An employer with 10 or fewer employees is permitted to communicate the emergency action plan orally to employees instead of maintaining a written plan."
    },
    {
      "quote_ref": "F005",
      "scope_refs": [
        "F004"
      ],
      "kind": "requirement",
      "meaning": "At a minimum, an emergency action plan must include procedures for reporting a fire or other emergency."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [
        "F004"
      ],
      "kind": "requirement",
      "meaning": "At a minimum, an emergency action plan must include procedures for emergency evacuation, including the type of evacuation and exit route assignments."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [
        "F004"
      ],
      "kind": "requirement",
      "meaning": "At a minimum, an emergency action plan must include procedures to be followed by employees who remain to operate critical plant operations before they evacuate."
    },
    {
      "quote_ref": "F008",
      "scope_refs": [
        "F004"
      ],
      "kind": "requirement",
      "meaning": "At a minimum, an emergency action plan must include procedures to account for all employees after evacuation."
    },
    {
      "quote_ref": "F009",
      "scope_refs": [
        "F004"
      ],
      "kind": "requirement",
      "meaning": "At a minimum, an emergency action plan must include procedures to be followed by employees performing rescue or medical duties."
    },
    {
      "quote_ref": "F010",
      "scope_refs": [
        "F004"
      ],
      "kind": "requirement",
      "meaning": "At a minimum, an emergency action plan must include the name or job title of every employee who may be contacted by employees who need more information about the plan or an explanation of their duties under the plan."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An employer must have and maintain an employee alarm system."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "The employee alarm system must use a distinctive signal for each purpose and must comply with the requirements in § 1910.165."
    },
    {
      "quote_ref": "F012:F013",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An employer must designate and train employees to assist in a safe and orderly evacuation of other employees."
    },
    {
      "quote_ref": "F015",
      "scope_refs": [
        "F014"
      ],
      "kind": "requirement",
      "meaning": "An employer must review the emergency action plan with each employee covered by the plan when the plan is developed or when the employee is assigned initially to a job."
    },
    {
      "quote_ref": "F016",
      "scope_refs": [
        "F014"
      ],
      "kind": "requirement",
      "meaning": "An employer must review the emergency action plan with each employee covered by the plan when the employee's responsibilities under the plan change."
    },
    {
      "quote_ref": "F017",
      "scope_refs": [
        "F014"
      ],
      "kind": "requirement",
      "meaning": "An employer must review the emergency action plan with each employee covered by the plan when the plan is changed."
    }
  ]
}
